// Bundled New Yorker ID card template (design 3a) with self-hosted fonts,
// base64-encoded so the serverless function needs no filesystem access.
// Source: dnyv/idcard/template.html. Tokens filled by api/_id-card.js.

export const ID_TEMPLATE_B64 = "";
export const idTemplate = () => Buffer.from(ID_TEMPLATE_B64, "base64").toString("utf8");
